// Нормализация входа: превращает любое обновление Telegram (текст, файл, кнопка) в единый плоский объект.
const upd = $input.first().json;
const cb = upd.callback_query || null;
const m = upd.message || {};
const msg = cb ? (cb.message || {}) : m;
const from = (cb ? cb.from : m.from) || {};
const chat = msg.chat || {};

const MAX_LEN = 3500;
const rawText = cb ? '' : String(m.text || m.caption || '');
let text = rawText.trim();
const truncated = text.length > MAX_LEN;
if (truncated) text = text.slice(0, MAX_LEN);

const attachments = [];
if (m.document) {
  attachments.push({
    name: String(m.document.file_name || 'document'),
    mime: String(m.document.mime_type || ''),
    size: Number(m.document.file_size || 0),
    kind: 'document',
  });
}
if (Array.isArray(m.photo) && m.photo.length) {
  const best = m.photo[m.photo.length - 1] || {};
  attachments.push({ name: 'photo_' + (m.message_id || '') + '.jpg', mime: 'image/jpeg', size: Number(best.file_size || 0), kind: 'photo' });
}

const CONFIRM_WORDS = /^(да|подтверждаю|подтвердить|верно|всё верно|все верно|ок|окей|ok|okay|согласен|согласна|регистрируй|регистрируйте|зарегистрировать)[.!\s]*$/i;
const CANCEL_WORDS = /^(отмена|отменить|отмени|cancel|стоп|не нужно|не надо)[.!\s]*$/i;
const COMMANDS = { '/start': 'start', '/help': 'start', '/new': 'new', '/cancel': 'cancel', '/status': 'status' };
const BUTTONS = { confirm: 'confirm', edit: 'edit', cancel: 'cancel' };

let input_type = 'unsupported';
let command = '';
let via_text = false;
if (cb) {
  input_type = BUTTONS[String(cb.data || '')] ? 'cb_' + BUTTONS[String(cb.data)] : 'unsupported';
} else if (text.startsWith('/')) {
  command = text.split(/[\s@]/)[0].toLowerCase();
  input_type = COMMANDS[command] || 'start';
} else if (attachments.length === 0 && CONFIRM_WORDS.test(text)) {
  input_type = 'cb_confirm';
  via_text = true;
} else if (attachments.length === 0 && CANCEL_WORDS.test(text)) {
  input_type = 'cb_cancel';
  via_text = true;
} else if (text || attachments.length) {
  input_type = 'content';
}

const user_name = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || '';

return [{
  json: {
    chat_id: String(chat.id !== undefined ? chat.id : (from.id || '')),
    user_id: String(from.id || ''),
    user_name,
    input_type,
    command,
    via_text,
    text,
    truncated,
    attachments,
    callback_query_id: cb ? cb.id : null,
    callback_data: cb ? String(cb.data || '') : '',
    callback_message_id: cb && cb.message ? cb.message.message_id : null,
    callback_message_text: cb && cb.message ? String(cb.message.text || '') : '',
    message_id: m.message_id || null,
    update_id: upd.update_id || null,
  },
}];

// Состояние диалога: «память» агента. Берёт заявки чата из Data Table, находит активную сессию и решает, что делать с входом.
const inp = $('Нормализация входа').first().json;

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.id !== undefined && r.id !== null && r.id !== '');
rows.sort((a, b) => Number(b.id) - Number(a.id));

const ACTIVE = ['collecting', 'awaiting_confirmation'];
const STALE_MS = 24 * 60 * 60 * 1000;

const latest = rows[0] || null;
let session = null;
let stale_dropped = false;
if (latest && ACTIVE.includes(latest.status)) {
  const t = Date.parse(latest.updatedAt || latest.createdAt || '');
  if (t && Date.now() - t > STALE_MS) stale_dropped = true;
  else session = latest;
}

let card = {};
if (session && session.card_json) {
  try { card = JSON.parse(session.card_json); } catch (e) { card = {}; }
}

const awaiting = !!session && session.status === 'awaiting_confirmation';

// action: content — разбор сообщения; confirm — финальная проверка и регистрация; quick — ответ без ИИ
let action = 'content';
let quick = '';
switch (inp.input_type) {
  case 'status':
    action = 'quick'; quick = 'status'; break;
  case 'new':
    action = 'quick'; quick = 'new'; break;
  case 'cancel':
  case 'cb_cancel':
    action = 'quick'; quick = session ? 'cancel' : 'idle_cancel'; break;
  case 'cb_edit':
    action = 'quick'; quick = session ? 'edit' : 'stale'; break;
  case 'cb_confirm':
    if (awaiting) action = 'confirm';
    else if (inp.via_text) action = 'content';
    else { action = 'quick'; quick = session ? 'confirm_not_ready' : 'stale'; }
    break;
  default:
    action = 'content';
}

const rand = Math.random().toString(36).slice(2, 6);
const request_uid = session && session.request_uid ? session.request_uid : 'R' + Date.now().toString(36) + rand;

return [{
  json: {
    ...inp,
    action,
    quick,
    mode: action === 'confirm' ? 'confirm' : 'process',
    has_session: !!session,
    session_status: session ? session.status : null,
    row_id: session ? session.id : null,
    request_uid,
    attempts: session ? Number(session.attempts || 0) : 0,
    request_text: session ? String(session.request_text || '') : '',
    card,
    stale_dropped,
    rows_brief: rows.slice(0, 5).map((r) => ({
      id: r.id,
      status: r.status,
      reg_number: r.reg_number || '',
      route: r.route || '',
      card_json: r.card_json || '',
      updatedAt: r.updatedAt || '',
    })),
  },
}];

// Быстрые действия без ИИ: статус, отмена, исправление, неактуальная кнопка, вне темы.
const ctx = $json;
const kind = ctx.quick || ctx.mode;
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const CUR = { RUB: '₽', USD: '$', EUR: '€', CNY: '¥', KZT: '₸', OTHER: '' };
const STATUS = {
  collecting: 'сбор данных',
  awaiting_confirmation: 'ждёт подтверждения',
  registered: 'зарегистрирована, идёт согласование',
  cancelled: 'отменена',
  escalated: 'требует помощи администратора',
};

const base = { request_uid: ctx.request_uid, chat_id: ctx.chat_id, user_name: ctx.user_name };
let text = '';
let save = null;

switch (kind) {
  case 'status': {
    const rows = ctx.rows_brief || [];
    if (!rows.length) {
      text = '📋 У вас пока нет заявок. Опишите договор — и я оформлю заявку.';
      break;
    }
    const lines = rows.map((r, i) => {
      let card = {};
      try { card = JSON.parse(r.card_json || '{}'); } catch (e) { card = {}; }
      const who = esc(card.counterparty_name || 'контрагент не указан');
      const sum = card.amount ? ' · ' + money(card.amount) + ' ' + (CUR[card.currency] || '') : '';
      const id = r.reg_number ? '№ ' + esc(r.reg_number) : 'черновик';
      return (i + 1) + '. ' + id + ' · ' + who + sum + ' — ' + (STATUS[r.status] || esc(r.status)) + (r.status === 'registered' && r.route ? '\n    маршрут: ' + esc(r.route) : '');
    });
    text = '📋 <b>Ваши заявки</b> (последние ' + rows.length + ')\n' + lines.join('\n');
    break;
  }
  case 'cancel':
    text = '❌ Заявка отменена. Чтобы создать новую, опишите договор или отправьте /new.';
    save = { ...base, status: 'cancelled' };
    break;
  case 'new':
    text = '🆕 Начинаем новую заявку' + (ctx.has_session ? ' (предыдущий черновик закрыт)' : '') + '. Опишите договор: тип, контрагент (название и ИНН), предмет, сумма, срок, условия оплаты.';
    if (ctx.has_session) save = { ...base, status: 'cancelled' };
    break;
  case 'edit':
    text = '✏️ Что нужно исправить? Напишите изменения одним сообщением, например: «сумма 15 млн, срок до 31.12.2027».';
    save = { ...base, status: 'collecting' };
    break;
  case 'idle_cancel':
    text = 'Сейчас нет активной заявки. Опишите договор, чтобы начать.';
    break;
  case 'confirm_not_ready':
    text = 'Пока нечего подтверждать — карточка ещё не готова. Ответьте на вопросы выше или отправьте /cancel.';
    break;
  case 'off_topic':
    text = ctx.has_session
      ? 'Это не похоже на данные по договору. Заявка сохранена — отправьте недостающие данные или /cancel, чтобы отменить.'
      : 'Я помогаю оформлять заявки на согласование договоров. Опишите договор: тип, контрагент, предмет, сумма и срок. Справка — /help.';
    break;
  default:
    text = 'Эта кнопка уже неактуальна: заявка обработана или отменена. Отправьте /new, чтобы создать новую.';
}

return [{ json: { chat_id: ctx.chat_id, text, keyboard: null, save } }];

// Слияние с карточкой: проверяет ответ ИИ (JSON), нормализует значения и аккуратно сливает их с карточкой из памяти.
const ctx = $('Состояние диалога').first().json;
const ref = $('Справочники и регламент').first().json.ref;

// 1. Ответ модели: объект (JSON Schema разобран узлом) или строка с JSON; иначе — ошибка разбора
let ex = $json.output && $json.output[0] && $json.output[0].content && $json.output[0].content[0]
  ? $json.output[0].content[0].text
  : null;
if (typeof ex === 'string') {
  // модель могла обернуть JSON в ```-блок или добавить пояснение — вырезаем сам объект
  const t = ex.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
  try { ex = JSON.parse(t); } catch (e) {
    const m = t.match(/\{[\s\S]*\}/);
    try { ex = m ? JSON.parse(m[0]) : null; } catch (e2) { ex = null; }
  }
}
const llm_ok = !!ex && typeof ex === 'object' && !Array.isArray(ex);
if (!llm_ok) ex = {};

const INTENTS = ['provide_info', 'new_request', 'question', 'off_topic'];
let intent = INTENTS.includes(ex.intent) ? ex.intent : 'provide_info';
// загрузка файла — всегда часть заявки, а не «вне темы»
if (intent === 'off_topic' && (ctx.attachments || []).length) intent = 'provide_info';
const fresh = intent === 'new_request';

const card = fresh ? {} : { ...(ctx.card || {}) };

// 2. Скалярные поля: только непустые новые значения перекрывают старые
const isIsoDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(Date.parse(s));
const put = (k, v) => { card[k] = v; };
const clean = (v) => (typeof v === 'string' ? v.trim() : v);

if (ref.types[ex.contract_type]) put('contract_type', ex.contract_type);
if (clean(ex.counterparty_name)) {
  const normN = (x) => String(x || '').toLowerCase().replace(/[^a-zа-яё0-9]/g, '');
  // сменили контрагента, а новый ИНН не назвали — старые реквизиты к новому названию не относятся
  if (card.counterparty_name && normN(card.counterparty_name) !== normN(ex.counterparty_name) && !ex.counterparty_inn) {
    delete card.counterparty_inn;
    delete card.counterparty_country;
    delete card.counterparty_is_foreign;
  }
  put('counterparty_name', clean(ex.counterparty_name));
}
let innDropped = false;
if (ex.counterparty_inn !== null && ex.counterparty_inn !== undefined) {
  const digits = String(ex.counterparty_inn).replace(/\D/g, '');
  // защита от «выдуманного» моделью ИНН: цифры должны реально присутствовать в сообщении пользователя
  const userDigits = String(ctx.text || '').replace(/\D/g, '');
  if (digits && userDigits.includes(digits)) put('counterparty_inn', digits);
  else if (digits) innDropped = true;
}
if (typeof ex.counterparty_is_foreign === 'boolean') put('counterparty_is_foreign', ex.counterparty_is_foreign);
if (clean(ex.counterparty_country)) put('counterparty_country', clean(ex.counterparty_country));
if (clean(ex.subject)) put('subject', clean(ex.subject));
if (typeof ex.amount === 'number' && isFinite(ex.amount) && ex.amount > 0) put('amount', ex.amount);
if (clean(ex.currency)) {
  const cur = String(ex.currency).toUpperCase();
  put('currency', ref.rates_rub[cur] !== undefined ? cur : 'OTHER');
}
if (typeof ex.vat_included === 'boolean') put('vat_included', ex.vat_included);
if (ex.start_date && isIsoDate(ex.start_date)) put('start_date', ex.start_date);
if (ex.end_date && isIsoDate(ex.end_date)) put('end_date', ex.end_date);
if (clean(ex.term_text)) put('term_text', clean(ex.term_text));
if (clean(ex.payment_terms)) put('payment_terms', clean(ex.payment_terms));
if (clean(ex.initiator_department)) put('initiator_department', clean(ex.initiator_department));
if (typeof ex.uses_standard_template === 'boolean') put('uses_standard_template', ex.uses_standard_template);

// 3. Списки объединяются без дублей
const union = (a, b) => {
  const out = [];
  const seen = new Set();
  for (const x of [].concat(a || [], b || [])) {
    const s = String(x).trim();
    const key = s.toLowerCase();
    if (s && !seen.has(key)) { seen.add(key); out.push(s); }
  }
  return out;
};
card.non_standard_terms = union(card.non_standard_terms, ex.non_standard_terms);
const claimed = Array.isArray(ex.attachments_claimed) ? ex.attachments_claimed.filter((c) => ref.attachment_labels[c]) : [];
card.attachments_claimed = union(card.attachments_claimed, claimed);

// 4. Файлы из Telegram: тип документа определяется по имени файла (детерминированные правила)
const ATT_RULES = [
  ['specification', /специф|specif/i],
  ['terms_of_reference', /(^|[\s_\-.])тз([\s_\-.]|$)|техзад|техническ\S*\s*задан|terms.?of.?ref/i],
  ['estimate', /смет|estimate/i],
  ['property_docs', /егрн|собственн|право.?устан|свидетельств/i],
  ['charter_docs', /устав|егрюл|огрн|учредит|charter/i],
  ['power_of_attorney', /доверенн/i],
  ['draft_contract', /договор|контракт|проект|contract|agreement|соглашен/i],
];
const classify = (name) => {
  for (const [code, re] of ATT_RULES) if (re.test(name)) return code;
  return 'other';
};
const files = Array.isArray(card.files) ? card.files.slice() : [];
for (const a of ctx.attachments || []) {
  if (!files.some((f) => f.name === a.name)) files.push({ name: a.name, type: classify(a.name) });
}
card.files = files;

// 5. Режим дальнейшей обработки
let mode = 'process';
if (!llm_ok) mode = 'error';
else if (intent === 'question') mode = 'question';
else if (intent === 'off_topic') mode = 'off_topic';

const prev = fresh ? '' : String(ctx.request_text || '');
const added = ctx.text || (ctx.attachments && ctx.attachments.length ? '[файл] ' + ctx.attachments.map((a) => a.name).join(', ') : '');
const request_text = ((prev ? prev + '\n---\n' : '') + added).slice(-6000);

const rand = Math.random().toString(36).slice(2, 6);
return [{
  json: {
    ...ctx,
    mode,
    intent,
    llm_ok,
    card,
    comment: (typeof ex.comment === 'string' ? ex.comment : '') + (innDropped ? ' ИНН из ответа ИИ не найден в вашем сообщении и проигнорирован.' : ''),
    question_text: typeof ex.question_text === 'string' && ex.question_text ? ex.question_text : (ctx.text || ''),
    request_text,
    attempts: fresh ? 0 : ctx.attempts,
    row_id: fresh ? null : ctx.row_id,
    request_uid: fresh ? 'R' + Date.now().toString(36) + rand : ctx.request_uid,
    session_status: fresh ? null : ctx.session_status,
    has_session: fresh ? false : ctx.has_session,
    new_session: fresh,
  },
}];

// RAG: поиск релевантных фрагментов регламента (BM25 по корпусу) — модель отвечает только по найденным фрагментам.
const ref = $('Справочники и регламент').first().json.ref;
const P = { ...$json };
const query = String(P.question_text || P.text || '');

const STOP = new Set(['что', 'как', 'какой', 'какие', 'какая', 'какое', 'нужно', 'нужны', 'нужен', 'надо', 'для', 'при', 'или', 'это', 'если', 'есть', 'мне', 'мой', 'где', 'когда', 'почему', 'сколько', 'можно', 'будет', 'кто', 'все', 'всех', 'чтобы', 'тоже', 'ещё', 'уже', 'так']);
const tokenize = (s) => (String(s).toLowerCase().match(/[a-zа-яё0-9]+/g) || [])
  .filter((w) => w.length > 2 && !STOP.has(w))
  .map((w) => w.slice(0, 5));

const docs = ref.regulation.map((r) => ({ r, toks: tokenize(r.title + ' ' + r.text) }));
const N = docs.length;
const avgdl = docs.reduce((s, d) => s + d.toks.length, 0) / N;
const qt = Array.from(new Set(tokenize(query)));
const df = {};
qt.forEach((t) => { df[t] = docs.filter((d) => d.toks.includes(t)).length; });

const k1 = 1.5;
const b = 0.75;
const chunks = docs
  .map((d) => {
    const tf = {};
    d.toks.forEach((t) => { tf[t] = (tf[t] || 0) + 1; });
    let score = 0;
    for (const t of qt) {
      if (!tf[t]) continue;
      const idf = Math.log(1 + (N - df[t] + 0.5) / (df[t] + 0.5));
      score += idf * ((tf[t] * (k1 + 1)) / (tf[t] + k1 * (1 - b + (b * d.toks.length) / avgdl)));
    }
    return { id: d.r.id, title: d.r.title, text: d.r.text, score: Math.round(score * 100) / 100 };
  })
  .filter((x) => x.score > 0)
  .sort((a, z) => z.score - a.score)
  .slice(0, 3);

return [{ json: { ...P, rag_query: query, chunks } }];

// Конверт «ответ по регламенту»: ответ модели (только по найденным фрагментам) либо запасной вариант — текст лучшего фрагмента.
const P = $('Поиск по регламенту (RAG)').first().json;
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let ans = $json.output && $json.output[0] && $json.output[0].content && $json.output[0].content[0]
  ? $json.output[0].content[0].text
  : null;
if (ans && typeof ans === 'object') ans = JSON.stringify(ans);
if (typeof ans !== 'string' || !ans.trim()) ans = null;

let text;
if (ans) {
  text = '📘 ' + esc(ans.trim().slice(0, 1400));
} else if (P.chunks.length) {
  text = '📘 По регламенту — <b>' + esc(P.chunks[0].title) + '</b>:\n' + esc(P.chunks[0].text);
} else {
  text = '📘 В регламенте нет ответа на этот вопрос — уточните его у юридического отдела.';
}
if (P.chunks.length) text += '\n\n<i>Источник: регламент, ' + P.chunks.map((c) => c.id).join(', ') + '</i>';
if (P.has_session) text += '\n\nЗаявка не потеряна: отправьте недостающие данные или /cancel, чтобы отменить.';
if (text.length > 3900) text = text.slice(0, 3890) + '…';

return [{ json: { chat_id: P.chat_id, text, keyboard: null, save: null } }];

// A1. Справочник контрагента (имитация CRM/ERP): находит контрагента по ИНН или названию, подставляет реквизиты и профиль риска.
const ref = $('Справочники и регламент').first().json.ref;
const P = { ...$json };
const card = { ...(P.card || {}) };
const notes = [];

// сбрасываем производные поля — они пересчитываются при каждом проходе
delete card.counterparty_known;
delete card.counterparty_risk;
delete card.counterparty_dir_id;

const normName = (s) => String(s || '')
  .toLowerCase()
  .replace(/[«»"'“”().,]/g, ' ')
  .replace(/(^|\s)(ооо|оао|зао|пао|ао|ип|ltd|llc|inc|gmbh)(?=\s|$)/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

let hit = null;
let matchedBy = '';
if (card.counterparty_inn) {
  hit = ref.directory.find((d) => d.inn && d.inn === card.counterparty_inn) || null;
  if (hit) matchedBy = 'inn';
}
if (!hit && card.counterparty_name) {
  const n = normName(card.counterparty_name);
  if (n.length >= 4) {
    hit = ref.directory.find((d) => d.aliases.some((a) => n.includes(a) || (n.length >= 6 && a.includes(n)))) || null;
    if (hit) matchedBy = 'name';
  }
}

if (hit) {
  card.counterparty_known = true;
  card.counterparty_risk = hit.risk;
  card.counterparty_dir_id = hit.id;
  if (!card.counterparty_name) card.counterparty_name = hit.name;
  if (matchedBy === 'name' && hit.inn) {
    if (!card.counterparty_inn) {
      card.counterparty_inn = hit.inn;
      notes.push('ИНН подставлен из справочника: ' + hit.inn);
    } else if (card.counterparty_inn !== hit.inn) {
      notes.push('ИНН в заявке (' + card.counterparty_inn + ') не совпадает с ИНН «' + hit.name + '» в справочнике (' + hit.inn + ') — проверьте');
    }
  }
  if (hit.foreign) {
    card.counterparty_is_foreign = true;
    if (!card.counterparty_country) card.counterparty_country = hit.country;
  } else if (card.counterparty_is_foreign === undefined || card.counterparty_is_foreign === null) {
    card.counterparty_is_foreign = false;
  }
  notes.push('Контрагент найден в справочнике: ' + hit.name + ' (риск: ' + ({ low: 'низкий', medium: 'средний', high: 'высокий' }[hit.risk] || hit.risk) + ')');
  if (hit.note) notes.push('Справочник: ' + hit.note);
} else if (card.counterparty_name || card.counterparty_inn) {
  card.counterparty_known = false;
  card.counterparty_risk = 'unknown';
  notes.push('Контрагент не найден в справочнике — считается новым: потребуются учредительные документы и проверка СБ');
}

if (P.truncated) notes.push('Сообщение длиннее 3500 символов — обработана только его первая часть');

return [{ json: { ...P, card, notes } }];

// A3. Проверка комплектности пакета (Quick Win №2): детерминированный чек-лист обязательных полей и приложений.
// Решение о полноте принимает код, а не модель: результат воспроизводим и проверяем.
const ref = $('Справочники и регламент').first().json.ref;
const P = { ...$json };
const c = P.card || {};
const T = c.contract_type || null;
const isNda = T === 'nda';
const foreign = c.counterparty_is_foreign === true;
const files = Array.isArray(c.files) ? c.files : [];
const claimed = Array.isArray(c.attachments_claimed) ? c.attachments_claimed : [];
const has = (code) => files.some((f) => f.type === code) || claimed.includes(code);

const checks = [];
const req = (code, ok, label, hint) => checks.push({ code, ok: !!ok, label, hint: hint || '' });
const warnings = [];

// контрольная сумма ИНН (10 цифр — организация, 12 — ИП/физлицо)
const innValid = (inn) => {
  if (!/^\d+$/.test(inn || '')) return false;
  const d = inn.split('').map(Number);
  const sum = (w, n) => w.reduce((s, k, i) => s + k * d[i], 0) % 11 % 10;
  if (d.length === 10) return sum([2, 4, 10, 3, 5, 9, 4, 6, 8]) === d[9];
  if (d.length === 12) return sum([7, 2, 4, 10, 3, 5, 9, 4, 6, 8]) === d[10] && sum([3, 7, 2, 4, 10, 3, 5, 9, 4, 6, 8]) === d[11];
  return false;
};

req('contract_type', T, 'Тип договора', 'поставка / услуги / подряд / аренда / NDA');
req('counterparty_name', c.counterparty_name, 'Контрагент', 'наименование организации');

if (foreign) {
  req('counterparty_country', c.counterparty_country, 'Страна регистрации контрагента', '');
} else if (!c.counterparty_inn) {
  req('counterparty_inn', false, 'ИНН контрагента', '10 цифр для организации, 12 — для ИП');
} else if (!innValid(c.counterparty_inn)) {
  req('counterparty_inn', false, 'Корректный ИНН контрагента', 'указанный ' + c.counterparty_inn + ' не проходит проверку контрольной суммы — проверьте цифры');
} else {
  req('counterparty_inn', true, 'ИНН контрагента');
}

req('subject', c.subject, 'Предмет договора', 'что поставляется / оказывается / арендуется');

if (!isNda) {
  const amountOk = typeof c.amount === 'number' && c.amount > 0 && c.amount < 1e12;
  req('amount', amountOk, 'Сумма договора', c.amount ? 'значение выглядит ошибочным: ' + c.amount : 'число и валюта, например «12 млн руб.»');
  req('currency', !amountOk || c.currency, 'Валюта договора', 'RUB / USD / EUR / CNY');
  req('payment_terms', c.payment_terms, 'Условия оплаты', 'например: оплата в течение 30 дней после приёмки');
}

let termOk = !!(c.end_date || c.term_text);
let termHint = 'дата окончания или период (например, «12 месяцев»)';
const today = new Date().toISOString().slice(0, 10);
if (c.start_date && c.end_date && c.end_date < c.start_date) {
  termOk = false;
  termHint = 'дата окончания ' + c.end_date + ' раньше даты начала ' + c.start_date;
} else if (c.end_date && c.end_date < today) {
  termOk = false;
  termHint = 'дата окончания ' + c.end_date + ' уже в прошлом';
}
req('term', termOk, 'Срок действия договора', termHint);

req('initiator_department', c.initiator_department, 'Подразделение-инициатор', 'нужно, чтобы определить руководителя для согласования');

// основа договора: типовой шаблон или проект контрагента
if (c.uses_standard_template === true) {
  req('template', true, 'Основа договора');
} else if (c.uses_standard_template === false) {
  req('draft_contract', has('draft_contract'), 'Проект договора контрагента', 'приложите файл');
} else {
  req('template', has('draft_contract'), 'Основа договора', 'типовой шаблон компании или проект контрагента (приложите файлом)');
}

// обязательные приложения по типу договора
for (const code of (ref.required_attachments[T] || [])) {
  req('att_' + code, has(code), 'Приложение: ' + ref.attachment_labels[code], 'приложите файл или напишите, что документ уже есть');
}
// новый контрагент — учредительные документы
if (c.counterparty_known === false && c.counterparty_name) {
  req('att_charter_docs', has('charter_docs'), 'Приложение: ' + ref.attachment_labels.charter_docs, 'контрагент новый — приложите файл');
}

// предупреждения (не блокируют запуск)
if ((c.non_standard_terms || []).length) warnings.push('Нестандартные условия: ' + c.non_standard_terms.join('; ') + ' — потребуется углублённая юридическая экспертиза');
if (c.counterparty_risk === 'high') warnings.push('Контрагент в перечне повышенного риска');
if (isNda && c.amount) warnings.push('Для NDA сумма не требуется — значение учтено только справочно');
if (P.comment) warnings.push(P.comment);

const missing = checks.filter((x) => !x.ok).map((x) => ({ code: x.code, label: x.label, hint: x.hint }));
const filled = checks.length - missing.length;
// прогресс = после ответа пользователя заполнено больше пунктов, чем раньше (для первой проверки прогресс засчитывается)
const progress = c._filled === undefined || c._filled === null ? true : filled > Number(c._filled);
const check = {
  complete: missing.length === 0,
  missing,
  warnings,
  total: checks.length,
  filled,
  progress,
};

return [{ json: { ...P, card: { ...c, _filled: filled }, check } }];

// A7. Подбор маршрута согласования: матрица согласования по сумме, типу, риску контрагента и нестандартным условиям (правила — в коде, не у модели).
const ref = $('Справочники и регламент').first().json.ref;
const P = { ...$json };
const c = P.card || {};
const check = P.check || { complete: false, missing: [], warnings: [], total: 0, filled: 0 };
const th = ref.thresholds;

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const CUR = { RUB: '₽', USD: '$', EUR: '€', CNY: '¥', KZT: '₸', OTHER: '' };
const ruDate = (iso) => (iso ? String(iso).split('-').reverse().join('.') : '');

// ---- маршрут ----
const amount = Number(c.amount || 0);
const rate = ref.rates_rub[c.currency || 'RUB'] || 1;
const amount_rub = Math.round(amount * rate);
const isNda = c.contract_type === 'nda';
const foreign = c.counterparty_is_foreign === true;
const known = c.counterparty_known === true;
const risk = c.counterparty_risk || 'unknown';
const nonStd = (c.non_standard_terms || []).length > 0;

const reasons = [];
const parallel = ['Юридический отдел'];
if (!isNda) parallel.push('Финансовый контролёр');

const sbWhy = [];
if (c.counterparty_name && !known) sbWhy.push('контрагент новый (нет в справочнике)');
if (foreign) sbWhy.push('иностранный контрагент');
if (risk === 'medium' || risk === 'high') sbWhy.push('риск контрагента: ' + (risk === 'high' ? 'высокий' : 'средний'));
if (amount_rub >= th.sb_amount) sbWhy.push('сумма ' + money(amount_rub) + ' ₽ ≥ ' + money(th.sb_amount) + ' ₽');
if (sbWhy.length) {
  parallel.push('Служба безопасности');
  reasons.push('СБ: ' + sbWhy.join('; '));
}

const sequential = ['Руководитель подразделения' + (c.initiator_department ? ' (' + c.initiator_department + ')' : '')];
const topWhy = [];
if (amount_rub >= th.top_amount) topWhy.push('сумма ' + money(amount_rub) + ' ₽ ≥ ' + money(th.top_amount) + ' ₽');
if (risk === 'high') topWhy.push('высокий риск контрагента');
if (nonStd && amount_rub >= th.top_nonstandard_amount) topWhy.push('нестандартные условия при сумме ≥ ' + money(th.top_nonstandard_amount) + ' ₽');
if (foreign && amount_rub >= th.top_foreign_amount) topWhy.push('иностранный контрагент при сумме ≥ ' + money(th.top_foreign_amount) + ' ₽');
if (topWhy.length) {
  sequential.push('Топ-менеджмент');
  reasons.push('Топ-менеджмент: ' + topWhy.join('; '));
}
if (nonStd) reasons.push('Юристы: нестандартные условия — углублённая экспертиза');

// ---- срок (рабочие дни) ----
const sla = ref.sla_days;
const expertiseDays = nonStd || foreign ? sla.expertise_extended : sla.expertise;
const totalDays = expertiseDays + sla.manager + (topWhy.length ? sla.top : 0);
const due = new Date();
let left = totalDays;
while (left > 0) {
  due.setDate(due.getDate() + 1);
  const wd = due.getDay();
  if (wd !== 0 && wd !== 6) left -= 1;
}
const dueIso = due.toISOString().slice(0, 10);

const route = {
  parallel,
  sequential,
  reasons,
  amount_rub,
  sla_days: totalDays,
  due_date: dueIso,
  template: ref.templates[c.contract_type] || null,
  text: parallel.join(' + ') + ' → ' + sequential.join(' → '),
};

// ---- блоки для сообщений ----
const rows = [];
rows.push('📄 <b>Карточка заявки</b> · заполнено ' + check.filled + ' из ' + check.total);
rows.push('Тип: ' + esc(ref.types[c.contract_type] || '—'));
let cp = esc(c.counterparty_name || '—');
if (c.counterparty_inn) cp += ', ИНН ' + esc(c.counterparty_inn);
if (c.counterparty_is_foreign && c.counterparty_country) cp += ', ' + esc(c.counterparty_country);
if (c.counterparty_known === true) cp += ' ✔ в справочнике';
if (c.counterparty_known === false) cp += ' ⚠ нет в справочнике';
rows.push('Контрагент: ' + cp);
rows.push('Предмет: ' + esc(c.subject || '—'));
if (!isNda) {
  rows.push('Сумма: ' + (c.amount ? money(c.amount) + ' ' + (CUR[c.currency] || esc(c.currency || '')) + (c.vat_included === true ? ' (с НДС)' : c.vat_included === false ? ' (без НДС)' : '') : '—'));
  rows.push('Оплата: ' + esc(c.payment_terms || '—'));
}
rows.push('Срок: ' + esc(c.end_date ? (c.start_date ? ruDate(c.start_date) + ' — ' : 'до ') + ruDate(c.end_date) : (c.term_text || '—')));
rows.push('Подразделение: ' + esc(c.initiator_department || '—'));
const base = c.uses_standard_template === true
  ? 'типовой шаблон' + (route.template ? ' ' + route.template : '')
  : (c.uses_standard_template === false || (c.files || []).some((f) => f.type === 'draft_contract') ? 'проект контрагента' : '—');
rows.push('Основа договора: ' + esc(base));
const fl = (c.files || []).map((f) => esc(f.name) + (f.type !== 'other' ? ' (' + esc(ref.attachment_labels[f.type] || f.type) + ')' : ''));
const cl = (c.attachments_claimed || []).filter((k) => !(c.files || []).some((f) => f.type === k)).map((k) => esc(ref.attachment_labels[k] || k) + ' (со слов инициатора)');
if (fl.length || cl.length) rows.push('Документы: ' + fl.concat(cl).join(', '));
(c.non_standard_terms || []).forEach((t) => rows.push('⚠ Нестандартное условие: ' + esc(t)));
(P.notes || []).forEach((t) => rows.push('ℹ️ ' + esc(t)));
const card_html = rows.join('\n');

const rt = [];
rt.push('🧭 <b>Маршрут согласования</b>');
rt.push('1. Параллельная экспертиза: ' + parallel.map(esc).join(' · '));
rt.push('2. ' + sequential.map(esc).join(' → '));
if (reasons.length) rt.push('Почему так: ' + reasons.map(esc).join(' | '));
rt.push('⏱ Плановый срок: ' + totalDays + ' раб. дн. (до ' + ruDate(dueIso) + ')');
const route_html = rt.join('\n');

return [{ json: { ...P, route, card_html, route_html } }];

// A8. Регистрация заявки: присваивает регистрационный номер, фиксирует статус и формирует уведомление о запуске маршрута.
const P = $('A7 Подбор маршрута').first().json;
const year = new Date().getFullYear();
const seq = P.row_id !== null && P.row_id !== undefined ? Number(P.row_id) : Date.now() % 100000;
const reg_number = 'ЗД-' + year + '-' + String(seq).padStart(5, '0');

let text = '🎉 <b>Заявка зарегистрирована: № ' + reg_number + '</b>\n\n';
text += P.route_html;
if (P.route.template) text += '\n📎 Шаблон договора: ' + P.route.template;
text += '\n\nМаршрут запущен. Статус заявки — по команде /status. Новая заявка — /new.';

return [{
  json: {
    chat_id: P.chat_id,
    text,
    keyboard: null,
    save: {
      request_uid: P.request_uid,
      chat_id: P.chat_id,
      user_name: P.user_name,
      status: 'registered',
      card_json: JSON.stringify(P.card),
      request_text: P.request_text,
      attempts: Number(P.attempts || 0),
      route: P.route.text,
      reg_number,
    },
  },
}];

// Конверт «карточка на подтверждение»: показывает собранную карточку и маршрут, ждёт решения инициатора (кнопки).
const P = $('A7 Подбор маршрута').first().json;

let text = P.card_html + '\n\n' + P.route_html;
(P.check.warnings || []).forEach((w) => {
  if (!text.includes(w)) text += '\n⚠ ' + String(w).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
});
text += '\n\n✅ <b>Пакет полный.</b> Проверьте данные и подтвердите — заявка будет зарегистрирована, а маршрут запущен автоматически. Если что-то неверно, нажмите «Исправить» или просто напишите правку.';
if (text.length > 3900) text = text.slice(0, 3890) + '…';

return [{
  json: {
    chat_id: P.chat_id,
    text,
    keyboard: 'confirm',
    save: {
      request_uid: P.request_uid,
      chat_id: P.chat_id,
      user_name: P.user_name,
      status: 'awaiting_confirmation',
      card_json: JSON.stringify(P.card),
      request_text: P.request_text,
      attempts: Number(P.attempts || 0),
      route: P.route.text,
    },
  },
}];

// Конверт «эскалация»: после исчерпания попыток уточнения заявка передаётся администратору СЭД (человек остаётся в контуре).
const P = $('A7 Подбор маршрута').first().json;
const ref = $('Справочники и регламент').first().json.ref;
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let text = P.card_html + '\n\n';
text += '🆘 <b>Не удалось собрать полный пакет: ' + ref.max_attempts + ' ответа подряд не продвинули заявку.</b>\n';
text += 'Заявка сохранена со статусом «требует помощи» — администратор СЭД свяжется с вами. Пока не хватает:\n';
text += P.check.missing.map((m, i) => (i + 1) + '. ' + esc(m.label)).join('\n');
text += '\n\nЧтобы начать заново, отправьте /new.';
if (text.length > 3900) text = text.slice(0, 3890) + '…';

return [{
  json: {
    chat_id: P.chat_id,
    text,
    keyboard: null,
    save: {
      request_uid: P.request_uid,
      chat_id: P.chat_id,
      user_name: P.user_name,
      status: 'escalated',
      card_json: JSON.stringify(P.card),
      request_text: P.request_text,
      attempts: Number(P.attempts || 0) + 1,
      route: P.route.text,
    },
  },
}];

// A5/A6. Конверт «уточняющие вопросы»: формулировки от ИИ сверяются с чек-листом; если ИИ не ответил или не покрыл пункт — берётся шаблон.
const P = $('A7 Подбор маршрута').first().json;
const ref = $('Справочники и регламент').first().json.ref;
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let llm = $json.output && $json.output[0] && $json.output[0].content && $json.output[0].content[0]
  ? $json.output[0].content[0].text
  : null;
if (typeof llm === 'string') {
  try { llm = JSON.parse(llm); } catch (e) { llm = null; }
}

let lead = '';
const byCode = {};
if (llm && typeof llm === 'object') {
  if (typeof llm.lead === 'string') lead = llm.lead.trim().slice(0, 300);
  for (const q of Array.isArray(llm.questions) ? llm.questions : []) {
    if (q && typeof q.code === 'string' && typeof q.text === 'string' && q.text.trim().length >= 5) {
      byCode[q.code] = q.text.trim().slice(0, 240);
    }
  }
}

const lines = P.check.missing.map((m, i) => {
  const fallback = m.label + (m.hint ? ' — ' + m.hint : '');
  return (i + 1) + '. ' + esc(byCode[m.code] || fallback);
});

// счётчик считает подряд идущие ответы БЕЗ прогресса; любой прогресс обнуляет его
const attempt = P.check.progress ? 0 : Number(P.attempts || 0) + 1;
let text = P.card_html + '\n\n';
if (lead) text += esc(lead) + '\n\n';
text += '❗ <b>Чтобы запустить согласование, уточните:</b>\n' + lines.join('\n');
text += '\n\nОтветьте одним сообщением (можно списком) или прикрепите файлы.';
if (attempt > 0) text += ' Ответов без прогресса: ' + attempt + ' из ' + ref.max_attempts + ' — после ' + ref.max_attempts + '-го заявка уйдёт администратору СЭД.';
text += ' /cancel — отменить.';
if (text.length > 3900) text = text.slice(0, 3890) + '…';

return [{
  json: {
    chat_id: P.chat_id,
    text,
    keyboard: null,
    save: {
      request_uid: P.request_uid,
      chat_id: P.chat_id,
      user_name: P.user_name,
      status: 'collecting',
      card_json: JSON.stringify(P.card),
      request_text: P.request_text,
      attempts: attempt,
      route: P.route.text,
    },
  },
}];
